$$
\begin{array}{l} A = \sum_ {n = 0} ^ {\infty} \int_ {n \pi} ^ {(n + 1) \pi} e ^ {- x} | \sin x | d x = \sum_ {n = 0} ^ {\infty} \left[ \int_ {2 n \pi} ^ {(2 n + 1) \pi} e ^ {- x} \sin x d x - \int_ {(2 n + 1) \pi} ^ {(2 n + 2) \pi} e ^ {- x} \sin x d x \right] \\ = \sum_ {n = 0} ^ {\infty} \left[ - \frac {\sin x + \cos x}{2} e ^ {- x} \Big | _ {2 n \pi} ^ {(2 n + 1) \pi} + \frac {\sin x + \cos x}{2} e ^ {- x} \Big | _ {(2 n + 1) \pi} ^ {(2 n + 2) \pi} \right] \\ = \frac {1}{2} \sum_ {n = 0} ^ {\infty} [ e ^ {- 2 n \pi} + 2 e ^ {- (2 n + 1) \pi} + e ^ {- (2 n + 2) \pi} ] = \frac {1}{2} \left[ \frac {1}{1 - e ^ {- 2 \pi}} + \frac {2 e ^ {- \pi}}{1 - e ^ {- 2 \pi}} + \frac {e ^ {- 2 \pi}}{1 - e ^ {- 2 \pi}} \right] = \frac {1}{2} \cdot \frac {1 + e ^ {- \pi}}{1 - e ^ {- \pi}}. \end{array}
$$
